const GRAUS = {
  "Crítico":{cls:"critico",doc:"c",prazo:"Imediato (24 h)",dias:1},
  "Alto":{cls:"alto",doc:"a",prazo:"7 dias",dias:7},
  "Médio":{cls:"medio",doc:"m",prazo:"30 dias",dias:30},
  "Baixo":{cls:"baixo",doc:"b",prazo:"90 dias",dias:90}
};

/* ══════════════════════════ estado ══════════════════════════ */
const CHAVE="sakuma-vistoria-v1";
let estado={cab:{unidade:"",setor:"",data:"",tecnico:"",cargo:"Técnico de Segurança do Trabalho",motivo:"Vistoria de rotina",aprovador:"",aprovadorCargo:"",codigo:""},itens:[]};
let proximoId=1;

const $=s=>document.querySelector(s);
const $$=s=>Array.from(document.querySelectorAll(s));
const esc=s=>String(s==null?"":s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const nl=s=>esc(s).replace(/\n/g,"<br>");

function toast(msg){const t=$("#toast");t.textContent=msg;t.hidden=false;clearTimeout(t._t);t._t=setTimeout(()=>{t.hidden=true},2600);}

function dataBR(iso){if(!iso)return"—";const p=iso.split("-");return p.length===3?`${p[2]}/${p[1]}/${p[0]}`:iso;}

function prazoData(dias){
  const base=estado.cab.data?new Date(estado.cab.data+"T12:00:00"):new Date();
  base.setDate(base.getDate()+dias);
  return base.toLocaleDateString("pt-BR");
}

/* ══════════════════════════ persistência ══════════════════════════ */
let salvarTimer=null;
function salvar(){
  clearTimeout(salvarTimer);
  salvarTimer=setTimeout(()=>{
    try{
      localStorage.setItem(CHAVE,JSON.stringify(estado));
      const h=new Date().toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"});
      $("#status-txt").innerHTML=`<span class="ok">✓</span> Rascunho salvo às ${h} neste navegador.`;
    }catch(e){
      $("#status-txt").innerHTML=`<span class="erro">⚠</span> O rascunho não coube na memória do navegador (fotos grandes). O relatório continua funcionando — gere o PDF antes de fechar a página.`;
    }
  },400);
}
function carregar(){
  try{
    const bruto=localStorage.getItem(CHAVE);
    if(!bruto)return;
    const d=JSON.parse(bruto);
    if(d&&d.cab){estado=d;proximoId=(estado.itens.reduce((m,i)=>Math.max(m,i.id||0),0))+1;}
  }catch(e){/* rascunho ilegível: começa limpo */}
}

/* ══════════════════════════ imagens ══════════════════════════ */
function comprimir(file,cb){
  const fr=new FileReader();
  fr.onload=()=>{
    const img=new Image();
    img.onload=()=>{
      const max=1400;
      let{width:w,height:h}=img;
      if(Math.max(w,h)>max){const f=max/Math.max(w,h);w=Math.round(w*f);h=Math.round(h*f);}
      const c=document.createElement("canvas");c.width=w;c.height=h;
      c.getContext("2d").drawImage(img,0,0,w,h);
      cb(c.toDataURL("image/jpeg",0.82));
    };
    img.onerror=()=>toast("Não foi possível ler essa imagem.");
    img.src=fr.result;
  };
  fr.onerror=()=>toast("Não foi possível ler esse arquivo.");
  fr.readAsDataURL(file);
}

/* ══════════════════════════ itens ══════════════════════════ */
function novoItem(chave){
  const a=ANOMALIAS[chave]||ANOMALIAS["outro"];
  return {
    id:proximoId++,aberto:true,chave,cat:a.cat,
    titulo:a.titulo,local:estado.cab.setor||"",
    encontrada:a.encontrada,risco:a.risco,grau:a.grau,
    normas:a.normas.slice(),requerida:a.requerida,acao:a.acao,
    prazo:GRAUS[a.grau].prazo,responsavel:"",
    evidencia:a.evidencia,pendencias:a.pendencias,
    fotoE:"",fotoR:""
  };
}

function aplicarAnomalia(item,chave){
  const a=ANOMALIAS[chave];if(!a)return;
  item.chave=chave;item.cat=a.cat;item.titulo=a.titulo;item.grau=a.grau;
  item.encontrada=a.encontrada;item.risco=a.risco;item.requerida=a.requerida;
  item.acao=a.acao;item.evidencia=a.evidencia;item.pendencias=a.pendencias;
  item.normas=a.normas.slice();item.prazo=GRAUS[a.grau].prazo;
}

function adicionar(){
  const it=novoItem("ext-obstruido");
  estado.itens.push(it);
  render();salvar();
  const el=document.querySelector(`[data-id="${it.id}"]`);
  if(el)el.scrollIntoView({behavior:"smooth",block:"center"});
}

/* ══════════════════════════ render: formulário ══════════════════════════ */
function opcoesAnomalia(sel){
  return CATEGORIAS.map(c=>{
    const opts=Object.entries(ANOMALIAS).filter(([,a])=>a.cat===c.id)
      .map(([k,a])=>`<option value="${k}"${k===sel?" selected":""}>${esc(a.titulo)}</option>`).join("");
    return `<optgroup label="${esc(c.nome)}">${opts}</optgroup>`;
  }).join("");
}

function chipNorma(k){
  const n=NORMAS[k];if(!n)return"";
  const it=n.item&&n.item!=="—"?` ${esc(n.item)}`:"";
  return `<button type="button" class="norma" data-norma="${k}">${esc(n.ref)}${it}${n.ok?"":' <span class="conf">confirmar item</span>'}</button>`;
}

function render(){
  const lista=$("#itens");
  $("#vazio").hidden=estado.itens.length>0;
  $("#rodape-add").hidden=estado.itens.length===0;
  $("#cont-itens").textContent=estado.itens.length;

  lista.innerHTML=estado.itens.map((it,i)=>{
    const g=GRAUS[it.grau]||GRAUS["Médio"];
    const minis=[it.fotoE,it.fotoR].filter(Boolean).map(s=>`<img src="${s}" alt="">`).join("");
    return `
    <article class="item g-${g.cls}" data-id="${it.id}" data-aberto="${it.aberto?1:0}">
      <div class="item-topo" data-toggle="${it.id}">
        <span class="seta">▶</span>
        <span class="item-num">${String(i+1).padStart(2,"0")}</span>
        <span class="item-tit">${esc(it.titulo)||"<em>Sem título</em>"}${it.local?` <em>· ${esc(it.local)}</em>`:""}</span>
        <span class="mini">${minis}</span>
        <span class="selo s-${g.cls}">${esc(it.grau)}</span>
      </div>
      <div class="item-corpo">
        <div class="fotos">
          <div class="foto encontrada${it.fotoE?" cheia":""}" data-foto="E" data-id="${it.id}" tabindex="0" role="button" aria-label="Anexar foto da situação encontrada">
            <span class="tag">Situação encontrada</span>
            ${it.fotoE?`<img src="${it.fotoE}" alt="Situação encontrada"><button class="tirar" type="button" data-remover="E" data-id="${it.id}" aria-label="Remover foto">×</button>`
              :`<span class="icone">▣</span><span class="ajuda">Clique, arraste o arquivo ou cole a imagem</span>`}
          </div>
          <div class="foto requerida${it.fotoR?" cheia":""}" data-foto="R" data-id="${it.id}" tabindex="0" role="button" aria-label="Anexar foto da situação requerida">
            <span class="tag">Situação requerida</span>
            ${it.fotoR?`<img src="${it.fotoR}" alt="Situação requerida"><button class="tirar" type="button" data-remover="R" data-id="${it.id}" aria-label="Remover foto">×</button>`
              :`<span class="icone">▤</span><span class="ajuda">Como o item deve estar — foto de referência ou pós-correção</span>`}
          </div>
        </div>

        <div class="grade" style="padding:0">
          <div class="campo largo"><label>Anomalia</label>
            <select data-campo="chave" data-id="${it.id}">${opcoesAnomalia(it.chave)}</select></div>
          <div class="campo largo"><label>Título do apontamento</label>
            <input type="text" data-campo="titulo" data-id="${it.id}" value="${esc(it.titulo)}"></div>
          <div class="campo"><label>Localização</label>
            <input type="text" data-campo="local" data-id="${it.id}" value="${esc(it.local)}" placeholder="Parede lateral direita, próximo ao portão"></div>
          <div class="campo"><label>Grau de risco</label>
            <select data-campo="grau" data-id="${it.id}">${Object.keys(GRAUS).map(k=>`<option${k===it.grau?" selected":""}>${k}</option>`).join("")}</select></div>
          <div class="campo"><label>Prazo</label>
            <input type="text" data-campo="prazo" data-id="${it.id}" value="${esc(it.prazo)}"></div>
          <div class="campo"><label>Responsável (cargo ou setor)</label>
            <input type="text" data-campo="responsavel" data-id="${it.id}" value="${esc(it.responsavel)}" placeholder="Encarregado do galpão"></div>
        </div>

        <div class="campo"><label>Requisito aplicável</label>
          <div class="normas">${it.normas.map(chipNorma).join("")||'<span class="dica">Nenhuma norma vinculada a esta anomalia.</span>'}</div>
          <div class="norma-txt" data-alvo="${it.id}" hidden></div>
        </div>

        <div class="campo"><label>Situação encontrada</label>
          <textarea data-campo="encontrada" data-id="${it.id}">${esc(it.encontrada)}</textarea></div>
        <div class="campo"><label>Risco associado</label>
          <textarea data-campo="risco" data-id="${it.id}">${esc(it.risco)}</textarea></div>
        <div class="campo"><label>Situação requerida</label>
          <textarea data-campo="requerida" data-id="${it.id}">${esc(it.requerida)}</textarea></div>
        <div class="campo"><label>Ação corretiva</label>
          <textarea data-campo="acao" data-id="${it.id}">${esc(it.acao)}</textarea></div>
        <div class="campo"><label>Evidência de encerramento</label>
          <textarea data-campo="evidencia" data-id="${it.id}">${esc(it.evidencia)}</textarea></div>
        <div class="campo"><label>Pendências de verificação em campo</label>
          <textarea data-campo="pendencias" data-id="${it.id}" placeholder="O que a foto não permite concluir">${esc(it.pendencias)}</textarea></div>

        <div class="rodape-item">
          <button class="bt bt-fantasma" type="button" data-duplicar="${it.id}">Duplicar</button>
          <button class="bt bt-fantasma bt-perigo" type="button" data-excluir="${it.id}">Excluir item</button>
        </div>
      </div>
    </article>`;
  }).join("");

  renderKpis();
  renderDoc();
}

function renderKpis(){
  const c={"Crítico":0,"Alto":0,"Médio":0,"Baixo":0};
  estado.itens.forEach(i=>{if(c[i.grau]!=null)c[i.grau]++;});
  $("#kpis").innerHTML=`
    <div class="kpi k-total"><div class="v">${estado.itens.length}</div><div class="r">Apontamentos</div></div>
    <div class="kpi k-critico"><div class="v">${c["Crítico"]}</div><div class="r">Crítico</div></div>
    <div class="kpi k-alto"><div class="v">${c["Alto"]}</div><div class="r">Alto</div></div>
    <div class="kpi k-medio"><div class="v">${c["Médio"]}</div><div class="r">Médio</div></div>
    <div class="kpi k-baixo"><div class="v">${c["Baixo"]}</div><div class="r">Baixo</div></div>`;
}

/* ══════════════════════════ render: relatório ══════════════════════════ */
function renderDoc(){
  const c=estado.cab;
  const g={"Crítico":0,"Alto":0,"Médio":0,"Baixo":0};
  estado.itens.forEach(i=>{if(g[i.grau]!=null)g[i.grau]++;});
  const imediatos=g["Crítico"];
  const pend=estado.itens.filter(i=>i.pendencias&&i.pendencias.trim());

  const cabLogo=`<img src="${LOGO}" alt="SAKUMA Agronegócios">`;

  const resumoTexto=estado.itens.length===0
    ? "Nenhuma não conformidade registrada nesta vistoria."
    : `Foram registrados ${estado.itens.length} apontamento${estado.itens.length>1?"s":""} nesta vistoria`+
      (imediatos?`, sendo ${imediatos} de grau crítico com correção de prazo imediato`:"")+
      `. O plano de ação consolidado consta ao final deste relatório e cada apontamento traz a evidência exigida para o seu encerramento.`;

  const fichas=estado.itens.map((it,i)=>{
    const gr=GRAUS[it.grau]||GRAUS["Médio"];
    const foto=(src,cls,leg)=>src
      ? `<figure class="${cls}"><img src="${src}" alt="${leg}"><figcaption>${leg}</figcaption></figure>`
      : `<figure class="${cls}"><div class="sem">Sem registro fotográfico</div><figcaption>${leg}</figcaption></figure>`;
    const normas=it.normas.map(k=>{
      const n=NORMAS[k];if(!n)return"";
      const item=n.item&&n.item!=="—"?`, item ${esc(n.item)}`:"";
      return `<div class="doc-norma"><b>${esc(n.ref)}${item}${n.ok?"":'<span class="conf">confirmar item</span>'}</b><i>${esc(n.txt)}</i></div>`;
    }).join("")||`<div class="doc-texto">Requisito não vinculado.</div>`;

    return `<div class="ficha">
      <div class="ficha-topo">
        <span class="n">${String(i+1).padStart(2,"0")}</span>
        <span class="t">${esc(it.titulo)}</span>
        <span class="g g-${gr.doc}">${esc(it.grau)}</span>
      </div>
      <div class="ficha-fotos">
        ${foto(it.fotoE,"e","Situação encontrada")}
        ${foto(it.fotoR,"r","Situação requerida")}
      </div>
      <div class="ficha-campos">
        <dl>
          <dt>Localização</dt><dd>${esc(it.local)||"—"}</dd>
          <dt>Situação encontrada</dt><dd>${nl(it.encontrada)||"—"}</dd>
          <dt>Risco associado</dt><dd>${nl(it.risco)||"—"}</dd>
          <dt>Requisito aplicável</dt><dd>${normas}</dd>
          <dt>Situação requerida</dt><dd>${nl(it.requerida)||"—"}</dd>
          <dt>Ação corretiva</dt><dd>${nl(it.acao)||"—"}</dd>
          <dt>Prazo</dt><dd>${esc(it.prazo)||"—"}</dd>
          <dt>Responsável</dt><dd>${esc(it.responsavel)||"—"}</dd>
          <dt>Evidência de encerramento</dt><dd>${nl(it.evidencia)||"—"}</dd>
          ${it.pendencias&&it.pendencias.trim()?`<dt>Pendências</dt><dd>${nl(it.pendencias)}</dd>`:""}
        </dl>
      </div>
    </div>`;
  }).join("");

  const plano=estado.itens.length?`
    <h2>Plano de ação consolidado</h2>
    <div class="env-tabela"><table class="plano">
      <thead><tr><th style="width:34px">Nº</th><th>Ação corretiva</th><th style="width:120px">Responsável</th><th style="width:92px">Prazo</th><th style="width:74px">Status</th></tr></thead>
      <tbody>${estado.itens.map((it,i)=>`<tr>
        <td>${String(i+1).padStart(2,"0")}</td>
        <td>${esc(it.acao)||"—"}</td>
        <td>${esc(it.responsavel)||"—"}</td>
        <td>${esc(it.prazo)||"—"}</td>
        <td>Aberto</td></tr>`).join("")}</tbody>
    </table></div>`:"";

  const pendencias=pend.length?`
    <h2>Pendências de verificação em campo</h2>
    <div class="doc-texto">${pend.map((it,i)=>`<p style="margin:0 0 6px"><b>Item ${String(estado.itens.indexOf(it)+1).padStart(2,"0")}</b> — ${nl(it.pendencias)}</p>`).join("")}</div>`:"";

  $("#doc").innerHTML=`
    <div class="doc-cab">${cabLogo}</div>
    <div class="doc-titulo">
      <h1>Relatório de Vistoria de Conformidade</h1>
      <div class="dir"><b>${esc(c.codigo)||"(sem número)"}</b> · ${dataBR(c.data)}<br>${esc(c.motivo)||""}</div>
    </div>
    <div class="linha-fina">${esc(c.unidade)||"Unidade não informada"}${c.setor?" · "+esc(c.setor):""}</div>

    <h2>Identificação</h2>
    <div class="doc-ident">
      <div><span>Unidade</span><b>${esc(c.unidade)||"—"}</b></div>
      <div><span>Setor / área</span><b>${esc(c.setor)||"—"}</b></div>
      <div><span>Data</span><b>${dataBR(c.data)}</b></div>
      <div><span>Técnico responsável</span><b>${esc(c.tecnico)||"—"}</b></div>
      <div><span>Cargo</span><b>${esc(c.cargo)||"—"}</b></div>
      <div><span>Motivo</span><b>${esc(c.motivo)||"—"}</b></div>
    </div>

    <h2>Resumo</h2>
    <div class="doc-resumo">
      <div class="doc-res t"><b>${estado.itens.length}</b><span>Apontamentos</span></div>
      <div class="doc-res c"><b>${g["Crítico"]}</b><span>Crítico</span></div>
      <div class="doc-res a"><b>${g["Alto"]}</b><span>Alto</span></div>
      <div class="doc-res m"><b>${g["Médio"]}</b><span>Médio</span></div>
      <div class="doc-res b"><b>${g["Baixo"]}</b><span>Baixo</span></div>
    </div>
    <div class="doc-texto">${esc(resumoTexto)}</div>

    ${estado.itens.length?`<h2>Não conformidades</h2>${fichas}`:""}
    ${plano}
    ${pendencias}

    <div class="doc-rodape">
      <div><span>Aprovado</span><b>${esc(c.aprovador)||"—"}</b><br>${esc(c.aprovadorCargo)||""}</div>
      <div style="text-align:right"><span>Feito por</span><b>${esc(c.tecnico)||"—"}</b><br>${esc(c.cargo)||""}</div>
    </div>
    <div class="doc-cod">${esc(c.codigo)||"(sem número)"} · Relatório de Vistoria · SAKUMA Agronegócios</div>`;
}

/* ══════════════════════════ eventos ══════════════════════════ */
function achar(id){return estado.itens.find(i=>i.id===Number(id));}

document.addEventListener("click",ev=>{
  const t=ev.target;

  if(t.closest("[data-novo]")){adicionar();return;}

  const tog=t.closest("[data-toggle]");
  if(tog&&!t.closest(".tirar")){
    const it=achar(tog.dataset.toggle);
    if(it){it.aberto=!it.aberto;
      const el=document.querySelector(`[data-id="${it.id}"]`);
      if(el)el.dataset.aberto=it.aberto?1:0;
      salvar();}
    return;
  }

  const rem=t.closest("[data-remover]");
  if(rem){
    const it=achar(rem.dataset.id);
    if(it){it[rem.dataset.remover==="E"?"fotoE":"fotoR"]="";render();salvar();}
    ev.stopPropagation();return;
  }

  const foto=t.closest("[data-foto]");
  if(foto&&!t.closest(".tirar")){
    const inp=document.createElement("input");
    inp.type="file";inp.accept="image/*";
    inp.onchange=()=>{
      const f=inp.files&&inp.files[0];if(!f)return;
      comprimir(f,url=>{
        const it=achar(foto.dataset.id);
        if(it){it[foto.dataset.foto==="E"?"fotoE":"fotoR"]=url;render();salvar();}
      });
    };
    inp.click();return;
  }

  const nrm=t.closest("[data-norma]");
  if(nrm){
    const n=NORMAS[nrm.dataset.norma];
    const cx=nrm.closest(".campo").querySelector(".norma-txt");
    if(n&&cx){
      const item=n.item&&n.item!=="—"?", item "+n.item:"";
      cx.innerHTML=`<b>${esc(n.ref)}${esc(item)}${n.ok?"":" · confirmar item na edição vigente"}</b>${esc(n.txt)}`;
      cx.hidden=false;
    }
    return;
  }

  const dup=t.closest("[data-duplicar]");
  if(dup){
    const it=achar(dup.dataset.duplicar);
    if(it){const copia=JSON.parse(JSON.stringify(it));copia.id=proximoId++;
      estado.itens.splice(estado.itens.indexOf(it)+1,0,copia);render();salvar();}
    return;
  }

  const exc=t.closest("[data-excluir]");
  if(exc){
    const it=achar(exc.dataset.excluir);
    if(it){estado.itens.splice(estado.itens.indexOf(it),1);render();salvar();toast("Apontamento excluído.");}
    return;
  }
});

document.addEventListener("input",ev=>{
  const el=ev.target;
  if(el.dataset.cab){estado.cab[el.dataset.cab]=el.value;renderDoc();salvar();return;}
  const campo=el.dataset.campo;
  if(!campo)return;
  const it=achar(el.dataset.id);if(!it)return;

  if(campo==="chave"){aplicarAnomalia(it,el.value);render();salvar();return;}
  if(campo==="grau"){it.grau=el.value;it.prazo=GRAUS[el.value].prazo;render();salvar();return;}
  it[campo]=el.value;
  if(campo==="titulo"||campo==="local"){
    const el2=document.querySelector(`[data-id="${it.id}"] .item-tit`);
    if(el2)el2.innerHTML=esc(it.titulo)+(it.local?` <em>· ${esc(it.local)}</em>`:"");
  }
  renderDoc();salvar();
});

/* arrastar e soltar */
document.addEventListener("dragover",ev=>{
  const f=ev.target.closest&&ev.target.closest("[data-foto]");
  if(f){ev.preventDefault();f.classList.add("sobre");}
});
document.addEventListener("dragleave",ev=>{
  const f=ev.target.closest&&ev.target.closest("[data-foto]");
  if(f)f.classList.remove("sobre");
});
document.addEventListener("drop",ev=>{
  const f=ev.target.closest&&ev.target.closest("[data-foto]");
  if(!f)return;
  ev.preventDefault();f.classList.remove("sobre");
  const file=ev.dataTransfer.files&&ev.dataTransfer.files[0];
  if(!file||!/^image\//.test(file.type)){toast("Solte um arquivo de imagem.");return;}
  comprimir(file,url=>{
    const it=achar(f.dataset.id);
    if(it){it[f.dataset.foto==="E"?"fotoE":"fotoR"]=url;render();salvar();}
  });
});

/* colar imagem no slot em foco */
document.addEventListener("paste",ev=>{
  const f=document.activeElement&&document.activeElement.closest&&document.activeElement.closest("[data-foto]");
  if(!f)return;
  const itens=ev.clipboardData&&ev.clipboardData.items;if(!itens)return;
  for(const i of itens){
    if(i.type&&i.type.indexOf("image")===0){
      const file=i.getAsFile();
      if(file)comprimir(file,url=>{
        const it=achar(f.dataset.id);
        if(it){it[f.dataset.foto==="E"?"fotoE":"fotoR"]=url;render();salvar();}
      });
      ev.preventDefault();return;
    }
  }
});

/* abas */
function aba(qual){
  const v=qual==="vistoria";
  $("#painel-vistoria").hidden=!v;
  $("#painel-relatorio").hidden=v;
  $("#t-vistoria").setAttribute("aria-selected",v);
  $("#t-relatorio").setAttribute("aria-selected",!v);
  window.scrollTo({top:0,behavior:"smooth"});
}
$("#t-vistoria").onclick=()=>aba("vistoria");
$("#t-relatorio").onclick=()=>{renderDoc();aba("relatorio");};

/* tema */
$("#bt-tema").onclick=()=>{
  const atual=document.documentElement.getAttribute("data-theme");
  const escuro=atual?atual==="dark":window.matchMedia("(prefers-color-scheme: dark)").matches;
  document.documentElement.setAttribute("data-theme",escuro?"light":"dark");
};

/* ações */
function imprimir(){renderDoc();aba("relatorio");setTimeout(()=>{try{window.print();}catch(e){toast("A impressão foi bloqueada aqui. Abra o arquivo HTML no Chrome e use Ctrl+P.");}},250);}
$("#bt-pdf").onclick=imprimir;
$("#bt-pdf-2").onclick=imprimir;
$("#bt-limpar").onclick=()=>{
  if(!estado.itens.length&&!estado.cab.unidade){toast("Não há nada para limpar.");return;}
  estado={cab:{unidade:"",setor:"",data:"",tecnico:"",cargo:"Técnico de Segurança do Trabalho",motivo:"Vistoria de rotina",aprovador:"",aprovadorCargo:"",codigo:""},itens:[]};
  proximoId=1;
  try{localStorage.removeItem(CHAVE);}catch(e){}
  preencherCabecalho();render();salvar();toast("Vistoria limpa.");
};

function preencherCabecalho(){
  $$("[data-cab]").forEach(el=>{el.value=estado.cab[el.dataset.cab]||"";});
}

/* ══════════════════════════ início ══════════════════════════ */
carregar();
if(!estado.cab.data)estado.cab.data=new Date().toISOString().slice(0,10);
$("#logo-img").src=LOGO;
preencherCabecalho();
render();
